/*
 * Microbenchmarks for data-dependent multiply timing on the C908.
 * The cases are generated by gen.py (see there for the case naming).
 */

#include <hal.h>
#include <stdio.h>
#include "perf.h"
#include "mul_timing_cases.h"

#define WARMUP_ITERATIONS  1000
#define ITER_PER_TEST      10
#define TEST_COUNT         1000

static void bench(const char *name, void (*fn)(void))
{
    init_perf_events();
    perf_calibrate_offset(ITER_PER_TEST, TEST_COUNT);
    for (unsigned cnt = 0; cnt < WARMUP_ITERATIONS; cnt++) {
        fn();
    }
    for (unsigned cnt = 0; cnt < TEST_COUNT; cnt++) {
        start_counting_events();
        for (unsigned cntp = 0; cntp < ITER_PER_TEST; cntp++) {
            fn();
        }
        stop_and_read_events();
    }
    calc_average(ITER_PER_TEST, TEST_COUNT);
    cleanup_perf_events();
    print_counter(name);
}

int main(void)
{
    printf("========= Mul Timing Benchmarks =========\n");
    printf("function, cycles, instructions, IPC, speedup, clean\n");
    for (unsigned i = 0; i < sizeof(mul_timing_cases) / sizeof(mul_timing_cases[0]); i++) {
        bench(mul_timing_cases[i].name, mul_timing_cases[i].fn);
    }
    return 0;
}
